"};",
"var sideView = (id, label, hasCount) => `<button type=\"button\" class=\"s-item v-${id}\" id=\"view-${id}\" data-view=\"${id}\" data-local data-nav title=\"${esc3(label)}\" aria-pressed=\"${id === \"all\"}\"><svg class=\"i\" viewBox=\"0 0 16 16\" aria-hidden=\"true\">${VIEW_ICONS[id]}</svg><span class=\"s-txt\">${esc3(label)}</span>${hasCount ? `<span class=\"s-n${id === \"needs\" ? \" hot\" : \"\"}\" id=\"count-${id}\"></span>` : \"\"}</button>`;",
