"<nav class=\"s-group s-views\" id=\"side-views\" aria-label=\"${esc3(s.pgViews)}\">${sideView(\"all\", s.pgOverview, false)}${sideView(\"needs\", s.pgNeeds, true)}${sideView(\"working\", s.pgWorking, true)}${sideView(\"others\", s.pgOthers, true)}${sideView(\"done\", s.pgDone, true)}</nav>",
"<div class=\"s-group s-agents\" id=\"side-agent-group\" role=\"group\" aria-labelledby=\"side-agents-label\" hidden><p class=\"s-label\" id=\"side-agents-label\">${esc3(s.pgAgents)}</p><div class=\"s-group\" id=\"side-agents\"></div></div>",
"<div class=\"s-group s-projects\" id=\"side-project-group\" role=\"group\" aria-labelledby=\"side-projects-label\" hidden><p class=\"s-label\" id=\"side-projects-label\">${esc3(s.pgProjects)}</p><div class=\"s-group\" id=\"side-projects\"></div></div>",
"<div class=\"s-foot\" id=\"side-foot\"></div>",
"</aside>",
"<div class=\"stage\">",
"<header class=\"head\" id=\"head\"><div class=\"col topbar\"><div class=\"brand\"><h1>${boardLogo(esc3(s.serveLiveHint))}</h1></div></div></header>",
"<template id=\"fresh-mark\">${boardIcon(44, \"\", true, \" is-arriving\")}</template>",
"<div id=\"offline\" role=\"status\" aria-live=\"polite\"></div>",
"<nav class=\"agents\" id=\"agents\" aria-label=\"${esc3(s.pgAgents)}\" hidden><div class=\"col agents-in\" id=\"chips\"></div><div class=\"col agent-note fx gone\" id=\"away-line\" role=\"status\" hidden><div class=\"fx-in\" id=\"away-line-in\"></div></div><div class=\"col agent-note\" id=\"agent-note\"></div></nav>",
"<main class=\"col page\">",
"<div id=\"board\"></div>",
"<details id=\"tidy-bulk\"><summary>${esc3(s.tidyBulk)}</summary><div class=\"fold-in\"><p><label>${esc3(s.tidyBulk)} <select id=\"tidy-kind\"><option value=\"stopped\">${esc3(s.tidyStopped)}</option><option value=\"agent\">${esc3(s.tidyAgent)}</option><option value=\"older\">${esc3(s.tidyOlder)}</option></select> <input id=\"tidy-value\" type=\"text\" inputmode=\"text\" placeholder=\"${esc3(s.tidyValue)}\" aria-label=\"${esc3(s.tidyValue)}\"></label></p><div class=\"acts\"><button type=\"button\" id=\"tidy-preview\" data-local>${esc3(s.tidyPreviewButton)}</button><button type=\"button\" id=\"tidy-confirm\" data-local disabled>${esc3(s.tidyConfirmButton)}</button><button type=\"button\" id=\"tidy-cancel\" data-local disabled>${esc3(s.tidyCancelButton)}</button></div></div></details><footer class=\"pfoot\" id=\"pfoot\"><a class=\"ver-link\" href=\"https://github.com/WenyuChiou/agent-board\" target=\"_blank\" rel=\"noopener\" title=\"${esc3(s.pgGithub)}\"><svg class=\"i\" viewBox=\"0 0 16 16\" role=\"img\" aria-label=\"GitHub\"><path d=\"${GITHUB_PATH}\"/></svg><span id=\"versions\"></span></a><span class=\"grow\"></span>${isLan ? `<p>${esc3(s.serveLanIdle)}</p>` : idleMs > 0 ? `<p>${esc3(s.serveIdleTimed(idleMs / 60000))}</p>` : \"\"}<span class=\"set-row\">${settingsToggle(s)}</span><button type=\"button\" class=\"icon-btn\" id=\"close\" data-static aria-label=\"${esc3(s.serveClose)}\" title=\"${esc3(s.serveClose)}\"><svg class=\"i\" viewBox=\"0 0 16 16\" aria-hidden=\"true\"><path d=\"${POWER_PATH}\"/></svg></button></footer>",
"<div id=\"note\" role=\"status\" aria-live=\"polite\"></div>",
"</main>",
"</div>",
"</div>",
"${settingsPanel(s, language, isLan, isLangOverridden)}",
