"  var sentLast = {};",
"  var agentPresence = {};",
"  var resultSlots = {};",
"  var lostResults = [];",
"  resultSlot(document.querySelector('.pfoot'), 'close', '', w('serveClose'));",
"  resultSlot(document.getElementById('tidy-bulk'), 'tidy', '', w('tidyBulk'));",
"  function resultSlot(card, key, revision, label) {",
"    card.setAttribute('data-card-key', key);",
